import envConfigs from '@cetus/types/src/config/envConfigs'
import { CetusPeripherySDK } from '@cetusprotocol/cetus-periphery-sdk'
import CetusClmmSDK from '@cetusprotocol/cetus-sui-clmm-sdk'
import { create, StateCreator } from 'zustand'

interface SDKState {
  peripherySdk: CetusPeripherySDK
  setPeripherySdk: (sdk: CetusPeripherySDK) => void
}

const store: StateCreator<SDKState> = (set, get) => ({
  peripherySdk: new CetusPeripherySDK(envConfigs.periphery_sdk_options, new CetusClmmSDK(envConfigs.clmm_sdk_options)),
  setPeripherySdk: (sdk: CetusPeripherySDK) => {
    set(() => ({
      peripherySdk: sdk
    }))
  }
})

const usePeripherySDKStore = create(store)
export default usePeripherySDKStore
