import { CommonTypeInfo, TransactionStatusType } from '@cetus/types/src/common-types'
import { Comma } from '@cetus/ui-kit'
import { Box, Link, Text, TextProps } from '@chakra-ui/react'
import { ReactNode } from 'react'

type ToastDescriptionProps = {
  status?: TransactionStatusType
  link?: string
  info?: CommonTypeInfo | undefined
}

export function ToastDescription(props: ToastDescriptionProps) {
  const { status = 'confirmation', link, info } = props

  const description = info?.toastDescriptionContent

  //  已提交
  if (status === 'submitted') {
    return (
      <>
        {description &&
          (typeof description === 'function' ? <DescriptionText>{description()}</DescriptionText> : <DescriptionText text={description} />)}
        {!description && link && (
          <Box as="div">
            <DescriptionText text="Confirmation is in progress. Check your transaction on" as="span" />
            &nbsp;&nbsp;
            <Link href={link} target="_blank" color="primary_green" fontSize="sm" textDecoration="none">
              here
            </Link>
          </Box>
        )}
      </>
    )
  }

  // 失败
  if (status === 'rejected') {
    return (
      <>
        {description &&
          (typeof description === 'function' ? <DescriptionText>{description()}</DescriptionText> : <DescriptionText text={description} />)}
        {!description && <DescriptionText text="Something went wrong" />}
      </>
    )
  }

  // 成功
  if (status === 'success') {
    return (
      <>
        {description &&
          (typeof description === 'function' ? <DescriptionText>{description()}</DescriptionText> : <DescriptionText text={description} />)}
      </>
    )
  }

  return <></>
}

interface DescriptionTextProps extends TextProps {
  text?: string
  children?: ReactNode
}

function DescriptionText(props: DescriptionTextProps) {
  const { text, children, ...rest } = props
  return children ? (
    <>{children}</>
  ) : (
    <Text fontSize="14px" color="primary_gray" {...rest}>
      <Comma value={text || ''} />
    </Text>
  )
}
