import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import usePumpConfigStore from '../../store/pumpConfig'

export function useGetGlobalConfig() {
  const { pumpSdk } = useInitSDK()
  const { globalConfig, setGlobalConfig, global_cache_time } = usePumpConfigStore()

  const fetchGlobalConfig = async () => {
    try {
      // 缓存15分钟
      if (new Date().getTime() - global_cache_time < 15 * 60 * 1000 && globalConfig) {
        return
      }
      const config = await pumpSdk.pumpModule.getGlobalConfig()
      console.log('🚀 ~ fetchGlobalConfig ~ config:', config)

      if (config) {
        setGlobalConfig(config)
      }

      return config
    } catch (error) {
      console.log('🚀 ~ file: useGetGlobalConfig.ts:42 ~ fetchGlobalConfig ~ error:', error)
    }
    return undefined
  }

  return {
    globalConfig,
    fetchGlobalConfig
  }
}
