import { Box, Button, HStack, Text, VStack } from '@chakra-ui/react'
import Icon from '../Icon'
import { FunctionNode, HandleEventType, ItemForActionProps, ItemWithDoubleLineProps, ItemWithSingleLineProps, ValueOption } from './type'
import { handleElement } from './util'
export const Regular = ({ value, ...rest }: ItemWithSingleLineProps) => {
  let color = 'text_caption'
  if ('color' in rest) {
    color = rest.color as string
  }
  const [Element, _color] = handleElement({ value })
  color = _color || color
  return <Text color={color}>{Element}</Text>
}

export const Action = ({ value, onChange, btn, ...rest }: ItemForActionProps) => {
  if (!value) {
    const { text, color = 'primary', bg_color = 'bg_secondary' } = btn
    return (
      <Button
        w="60px"
        h="20px"
        borderRadius="4px"
        color={color}
        bgColor={bg_color}
        size="xs"
        onClick={(...args) => onChange?.(HandleEventType.Add, ...args)}
      >
        {text}
      </Button>
    )
  }
  let color = 'text_caption'
  if ('color' in rest) {
    color = rest.color || color
  }
  const [Element, _color] = handleElement({ value })
  color = _color || color
  return (
    <HStack>
      <Text color={color}>{Element}</Text>
      <Icon xlinkHref="#icon-icon_edit" onClick={(...args) => onChange?.(HandleEventType.Edit, ...args)} />
      <Icon xlinkHref="#icon-icon_close" onClick={(...args) => onChange?.(HandleEventType.Delete, ...args)} />
    </HStack>
  )
}

export const Divider = ({ value }: ItemWithDoubleLineProps) => {
  let color1 = 'text_caption',
    color2 = 'text_paragraph'
  const [Element1, _color1] = handleElement({ value: value[0] })
  const [Element2, _color2] = handleElement({ value: value[1] })
  color1 = _color1 || color1
  color2 = _color2 || color2
  return (
    <HStack>
      <Text color={color1}>{Element1}</Text>
      <Text color={color2}>/ {Element2}</Text>
    </HStack>
  )
}

export const Double = ({ value, onChange }: ItemWithDoubleLineProps) => {
  let color1 = 'text_caption',
    color2 = 'text_paragraph'
  const [Element1, _color1] = handleElement({ value: value[0] })
  const [Element2, _color2] = handleElement({ value: value[1] })
  color1 = _color1 || color1
  color2 = _color2 || color2
  return (
    <VStack gap="0.2em" alignItems="flex-end">
      <HStack h="12px">
        <Text color={color1}>{Element1}</Text>
        {typeof value[0] === 'object' && (value[0] as ValueOption)?.editable && (
          <Icon onClick={(...args) => onChange?.(HandleEventType.Edit, ...args)} xlinkHref="#icon-icon_edit" />
        )}
      </HStack>
      <Text h="12px" color={color2}>
        {Element2}
      </Text>
    </VStack>
  )
}

export const Cos = ({ value }: { value: FunctionNode }) => {
  return typeof value === 'function' ? (
    value()
  ) : (
    <Box fontSize="14px" color="text_caption">
      {value}
    </Box>
  )
}
