import usePumpTokenListStore from '@/store/pumpTokenList'
import { CacheClmmInfo, PumpToken } from '@/type/pump'
import usePumpSDKStore from '@cetus/stores/src/usePumpSDKStore'
import { TickMath, getObjectFields } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, MEMEDecimal } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SuiObjectResponse } from '@mysten/sui/client'
import { SUI_DECIMALS } from '@mysten/sui/utils'
import BN from 'bn.js'
import { v4 } from 'uuid'

export function useGetClmmPoolList() {
  const { pumpSdk } = usePumpSDKStore()
  const { cacheClmmInfo, setCacheClmmInfo } = usePumpTokenListStore()
  // 为避免重复请求 增加 缓存60s
  const cacheIntervalTime = 60 * 1000

  const fetchClmmData = async (list: PumpToken[], uuid: string = v4()) => {
    const clmmPoolList = list

      .filter(item => item.status >= BondingCurveStatus.MIGRATED && item.TokenDetail.clmm_pool.length > 0)
      .map(item => item.TokenDetail.clmm_pool)

    console.log('🚀 ~ file: useGetClmmPoolList.ts:19 ~ fetchClmmData ~ clmmPoolList:', clmmPoolList)

    const fixList: CacheClmmInfo[] = []

    if (clmmPoolList.length > 0) {
      const unFondList: string[] = []
      // 缓存
      clmmPoolList.forEach(poolId => {
        const info = cacheClmmInfo[poolId]
        const nowTime = new Date().getTime()
        if (info && nowTime - info.last_update_time < cacheIntervalTime) {
          fixList.push(info)
        } else {
          unFondList.push(poolId)
        }
      })

      console.log('🚀 ~ file: useGetClmmPoolList.ts:38 ~ fetchClmmData ~ fixList:', fixList)

      if (unFondList.length > 0) {
        // api接口
        const res: SuiObjectResponse[] = await pumpSdk.fullClient.batchGetObjects(unFondList, { showContent: true })
        res.forEach(item => {
          const fields = getObjectFields(item)
          const poolId = fields.id.id
          const current_ui_price = TickMath.sqrtPriceX64ToPrice(new BN(fields.current_sqrt_price), MEMEDecimal, SUI_DECIMALS).toString()
          const info: CacheClmmInfo = {
            pool_id: poolId,
            current_ui_price: current_ui_price,
            current_sqrt_price: fields.current_sqrt_price,
            liquidity: fields.liquidity,
            last_update_time: new Date().getTime(),
            coin_a: fields.coin_a,
            coin_b: fields.coin_b
          }
          setCacheClmmInfo(info)
          fixList.push(info)
        })

        console.log('🚀 ~ file: useGetClmmPoolList.ts:56 ~ fetchClmmData ~ fixList:', fixList)
      }

      // 更新数据
      if (fixList.length > 0) {
        fixList.forEach(item => {
          const findInfo = list.find(pool => pool.TokenDetail.clmm_pool === item.pool_id)
          if (findInfo) {
            findInfo.current_ui_price = item.current_ui_price
            findInfo.current_sqrt_price = item.current_sqrt_price
            findInfo.liquidity = item.liquidity
          }
        })

        console.log('🚀 ~ file: useGetClmmPoolList.ts:70 ~ fetchClmmData ~ list:', list)

        return {
          list,
          uuid
        }
      }
    }

    return undefined
  }

  return {
    fetchClmmData
  }
}
