import { PublishFee } from '@/type/pump'
import { getFeeCoin } from '@/utils/pumpUtils'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import usePumpConfigStore from '../../store/pumpConfig'

export function useGetPublishFee() {
  const { pumpSdk } = useInitSDK()
  const { publishFeeList, setPublishFeeList, publish_fee_cache_time } = usePumpConfigStore()
  const { getTokenInfo, fetchTokenInfo } = useGetToken()

  const fetchPublishFee = async () => {
    try {
      // 缓存15分钟
      if (new Date().getTime() - publish_fee_cache_time < 15 * 60 * 1000 && publishFeeList.length > 0) {
        return
      }
      const feeList = await pumpSdk.pumpModule.getPublishTokenFee()

      const list: PublishFee[] = []
      for (const fee of feeList) {
        let coinInfo = getFeeCoin(fee.fee_coin_type) || getTokenInfo()
        if (!coinInfo) {
          coinInfo = await fetchTokenInfo(fee.fee_coin_type)
        }

        if (coinInfo) {
          const info: PublishFee = {
            ...coinInfo,
            amount: fee.fee_amount,
            amount_display: fromDecimalsAmount(fee.fee_amount, coinInfo.decimals).toString()
          }
          list.push(info)
        }
      }

      if (list.length > 0) {
        setPublishFeeList(list)
      }

      console.log('🚀 ~ file: useGetPublishFee.ts:36 ~ fetchPublishFee ~ list:', list)

      return list
    } catch (error) {
      console.log('🚀 ~ file: useGetPublishFee.ts:42 ~ fetchPublishFee ~ error:', error)
    }
    return []
  }

  return {
    publishFeeList,
    fetchPublishFee
  }
}
