import usePumpTokenListStore from '@/store/pumpTokenList'
import usePumpTokenListCacheStore from '@/store/pumpTokenListCache'
import { queryTokenListPath } from '@/type/api'
import { PumpToken, PumpTokenListQuery } from '@/type/pump'
import { PumpUtils } from '@/utils/pumpUtils'
import { isUpperCaseOrNumbersOrSymbols } from '@cetus/utils'
import { useState } from 'react'
import { usePumpApiDomain } from '../common/usePumpApiDomain'
import { useGetClmmPoolList } from './useGetClmmPoolList'

export function usePumpTokenList() {
  const {
    pumpTokenListRefreshLoading,
    setPumpTokenListRefreshLoading,
    pumpTokenListLordMoreLoading,
    setPumpTokenListLordMoreLoading,
    pumpTokenList,
    setPumpTokenList,
    hasMoreData,
    setHasMoreData,
    setMaxPage,
    maxPage
  } = usePumpTokenListStore()

  const { fetchGetByApi } = usePumpApiDomain()

  const { cachePumpTokenList, setCachePumpTokenList } = usePumpTokenListCacheStore()

  const { fetchClmmData } = useGetClmmPoolList()

  const [isLoadMoreError, setIsLoadMoreError] = useState<boolean>(false)

  const fetchPumpTokenList = async (query: PumpTokenListQuery, forceRefresh: boolean = false) => {
    const { page, page_size = 10, if_asc = false, order_by_type = 'time', query_filter_value, if_on_dex } = query
    setIsLoadMoreError(false)
    const params = new URLSearchParams({
      page: String(page),
      page_size: String(page_size),
      if_asc: String(if_asc),
      order_by_type
    })

    if (query_filter_value) {
      params.set('query_filter_value', query_filter_value)
      const isCoinType = query_filter_value.startsWith('0x')
      if (isCoinType) {
        params.set('query_filter_type', 'coin_type')
      } else if (isUpperCaseOrNumbersOrSymbols(query_filter_value)) {
        params.set('query_filter_type', 'ticker')
      } else {
        params.set('query_filter_type', 'name')
      }
    }

    if (if_on_dex !== undefined) {
      params.set('if_on_dex', String(if_on_dex))
    }

    try {
      if (page === 1) {
        if (pumpTokenList.length === 0 || forceRefresh) {
          setPumpTokenListRefreshLoading(true)
        }
      } else {
        setPumpTokenListLordMoreLoading(true)
      }

      const response = await fetchGetByApi(`${queryTokenListPath}?${params.toString()}`)
      console.log('🚀 ~ fetchPumpTokenList ~ response:', response)
      const list: PumpToken[] = response.tokenVolumes

      const maxPage = response.maxPage
      if (maxPage) {
        setMaxPage(Number(maxPage))
      }

      if (list) {
        list.forEach((item: any) => {
          PumpUtils.formatPumpToken(item)
        })
        const isAppend = false
        setPumpTokenList(list, isAppend)
        setHasMoreData(page < Number(maxPage))
        // 异步获取Clmm 相关信息
        fetchClmmData([...list])
      } else {
        setHasMoreData(false)
      }
      //持久化缓存
      if (page === 1 && order_by_type === 'time' && !if_asc && list.length > 0) {
        setCachePumpTokenList(list)
      }
      console.log('🚀 ~ file: usePumpTokenList.ts:9 ~ fetchPumpTokenList ~ list:', list)
      return list
    } catch (error) {
      setHasMoreData(false)
      console.log('🚀 ~ file: usePumpTokenList.ts:21 ~ fetchPumpTokenList ~ error:', error)
      setIsLoadMoreError(true)

      if (page === 1) {
        setPumpTokenList(cachePumpTokenList, false)
        fetchClmmData([...cachePumpTokenList])
      }
    } finally {
      setPumpTokenListRefreshLoading(false)
      setPumpTokenListLordMoreLoading(false)
    }
  }

  return {
    fetchPumpTokenList,
    pumpTokenList,
    pumpTokenListLordMoreLoading,
    pumpTokenListRefreshLoading,
    hasMoreData,
    isLoadMoreError,
    maxPage
  }
}
