import { HStack } from '@chakra-ui/react'
import SingleCoinImage from './SingleCoinImage'
export default function CoinPairImage(props: {
  coinAIconUrl?: string
  coinBIconUrl?: string
  showATag?: boolean
  showBTag?: boolean
  w?: string
  p?: string
  variant?: 'border' | ''
  ml?: string
}) {
  const { coinAIconUrl, coinBIconUrl, ml, showATag, showBTag, ...rest } = props
  return (
    <HStack gap="0px">
      <SingleCoinImage imageUrl={coinAIconUrl} {...rest} showTag={showATag} />
      <SingleCoinImage imageUrl={coinBIconUrl} {...rest} ml={ml ? ml : '0px'} showTag={showBTag} />
    </HStack>
  )
}
