import { CommonTypeInfo, TransactionStatusType } from '@cetus/types/src/common-types'
import { Icon, Spinner } from '@cetus/ui-kit'
import { HStack, Heading, Image } from '@chakra-ui/react'

type ToastTitleProps = {
  status?: TransactionStatusType
  info?: CommonTypeInfo | undefined
}

export function ToastTitle(props: ToastTitleProps) {
  const { status = 'confirmation', info } = props

  //  已提交
  if (status === 'submitted') {
    return (
      <>
        <HStack>
          <Spinner />
          <TitleText text="Transaction in progress" />
        </HStack>
      </>
    )
  }

  // 失败
  if (status === 'rejected') {
    return (
      <HStack gap="0px">
        <Icon xlinkHref="#icon-icon_close" variant="error" />(
        <HStack>
          <TitleText text={info?.toastTitleText || 'Transaction failed'} color="primary_red" />
        </HStack>
        )
      </HStack>
    )
  }

  // 成功
  if (status === 'success') {
    return (
      <>
        <HStack>
          {info?.iconUrl ? (
            <Image src={info.iconUrl} h="20px" alt="icon" borderRadius="4px" />
          ) : (
            <Icon xlinkHref="#icon-icon_check" svgFill="primary" />
          )}
          <TitleText text={info?.toastTitleText} />
        </HStack>
      </>
    )
  }

  return <></>
}

export function TitleText(props: { text?: string; color?: string }) {
  const { text, color = 'text_caption' } = props
  return (
    <Heading fontSize="14px" fontWeight="400" color={color} whiteSpace="nowrap">
      {text}
    </Heading>
  )
}
