import Header_Image from '@/assets/images/create_header.png'
import { FormInput, FormValueGroup, Label, Required, UploadLimitToast } from '@/components/create'
import { excludeCharValidate, formInputStyle } from '@/components/create/utils'
import CreateTokenModel from '@/components/modal/CreateTokenModel'
import { useCreateToken } from '@/hook/pump/useCreateToken'
import { useGetPublishFee } from '@/hook/pump/useGetPublishFee'
import { PublishFee } from '@/type/pump'
import {
  BlankSpaceRegex,
  DiscordRegex,
  ExcludeCNCharRegex,
  ExcludeSpecialCharRegex,
  SelectTab,
  SymbolExcludeSpecialCharRegex,
  SymbolLimitRegex,
  TelegramRegex,
  WebSiteUrlRegex,
  XUrlRegex
} from '@cetus/design'
import { Upload } from '@cetus/design/src/components/common'
import { useGetTokenBalance } from '@cetus/hooks/src/useTokenBalance'
import { useAccountStore } from '@cetus/stores'
import { Icon } from '@cetus/ui-kit'
import { d } from '@cetus/utils'
import { Box, Button, Center, FormControl, HStack, Heading, Input, Stack, Text, Textarea, VStack, useToast } from '@chakra-ui/react'
import { useDeepCompareEffect } from 'ahooks'
import { Field, Form, Formik } from 'formik'
import { useEffect, useRef, useState } from 'react'

function Create() {
  const [params, setParams] = useState<{ [key: string]: any }>({})
  const { currentAccount, accounts, onWalletModal, saveAccounts } = useAccountStore()
  const { handleSubmitPublishToken, setIsOpenModal, isOpenModal, createTokenModelOptions, hasCreated } = useCreateToken()
  const [loading, setLoading] = useState(false)
  const { publishFeeList, fetchPublishFee } = useGetPublishFee()
  const [feeList, setFeeList] = useState<PublishFee[]>([])
  const uploadRef = useRef(null)
  const nameRef = useRef(null)
  const symbolRef = useRef(null)
  const symbolInputRef = useRef<React.MutableRefObject<HTMLInputElement>>(null)
  const descriptionRef = useRef(null)
  const websiteRef = useRef(null)
  const discordRef = useRef(null)
  const telegramRef = useRef(null)
  const xUrlRef = useRef(null)
  const toast = useToast()
  const handleFeeChange = (item: any) => {
    setParams({ ...params, fee: item?.label })
  }

  const handleImageChange = (files: File[]) => {
    const file = files[0]
    setParams({ ...params, image: file })
  }

  useEffect(() => {
    fetchPublishFee()
  }, [])

  useDeepCompareEffect(() => {
    if (publishFeeList && publishFeeList.length > 0) {
      const suiIndex = publishFeeList.findIndex(item => item.symbol === 'SUI')
      if (suiIndex > -1) {
        const tempList = [...publishFeeList]
        const suiFee = tempList[suiIndex]
        tempList.splice(suiIndex, 1)
        setFeeList([suiFee, ...tempList])
      }
    }
  }, [publishFeeList])

  useDeepCompareEffect(() => {
    if (feeList && feeList.length > 0) {
      setParams({ ...params, fee: `${feeList[0]?.amount_display} ${feeList[0]?.symbol}` })
    }
  }, [feeList])

  const { balanceInfo: tokenABalanceInfo } = useGetTokenBalance(feeList?.[0])
  const { balanceInfo: tokenBBalanceInfo } = useGetTokenBalance(feeList?.[1])

  const isInvalidBalance = () => {
    if (feeList && feeList.length && params?.fee) {
      if (feeList?.[0]?.symbol === params?.fee?.split(' ')?.[1]) {
        return d(tokenABalanceInfo?.balance || 0).lt(feeList?.[0]?.amount || 0)
      } else {
        return d(tokenBBalanceInfo?.balance || 0).lt(feeList?.[1]?.amount || 0)
      }
    }
    return false
  }

  const [formikHelpers, setFormikHelpers] = useState<any>()

  useEffect(() => {
    if (hasCreated && formikHelpers) {
      formikHelpers.resetForm({ values: { image: undefined, name: '', symbol: '', description: '', website: '', x: '', discord: '', telegram: '' } })
      setParams({ fee: `${feeList[0]?.amount_display} ${feeList[0]?.symbol}` })
      uploadRef?.current?.handleClear?.()
    }
  }, [hasCreated])

  const onSubmit = async (values: any, formikHelpers: any) => {
    setFormikHelpers(formikHelpers)
    if (loading) return
    setLoading(true)
    try {
      const uploadInfo = values.image[0]
      const feeParams = (feeList || []).find((item: any) => item.symbol === params.fee.split(' ')[1])
      await handleSubmitPublishToken({
        tokenTicker: values.symbol.trim(),
        tokenName: values.name.trim(),
        tokenDescription: values.description.trim(),
        tokenIconUrl: uploadInfo.fileUrl,
        tokenTwitterLink: values.x,
        tokenTelegramLink: values.telegram,
        tokenWebsiteUrl: values.website,
        tokenDiscordUrl: values.discord,
        sig: uploadInfo.sig,
        fee: {
          fee_amount: feeParams?.amount || '0',
          fee_coin_type: feeParams?.coin_type || '',
          decimals: feeParams?.decimals || 0,
          symbol: feeParams?.symbol || '',
          name: feeParams?.name || '',
          iconUrl: feeParams?.logo_url || ''
        }
      })
    } catch (error) {
      console.log('🚀 ~ file: Create.tsx:47 ~ onSubmit ~ error:', error)

      throw new Error('create token error')
    } finally {
      setLoading(false)
    }
  }
  return (
    <VStack mt={{ base: '20px', lg: '28px' }} align="flex-start" gap={{ base: '4px', lg: '0.5rem' }}>
      <Center
        w="100%"
        h={{ base: '112px', lg: '157px' }}
        backgroundImage={Header_Image}
        backgroundRepeat="no-repeat"
        backgroundSize="contain"
        backgroundPosition="right"
      >
        <Heading height="60px" lineHeight="60px" fontSize={{ base: '18px', md: '24px', lg: '40px' }} fontWeight="bold" color="text_caption">
          Launch Your token on Cetus Pump
        </Heading>
      </Center>

      <Box
        margin={{ base: '0px', lg: '0px 93px' }}
        bg="form_card_bg"
        borderRadius="16px"
        p={{ base: '8px', lg: '28px' }}
        minW={{ base: '100%', lg: '696px' }}
      >
        <Formik
          initialValues={{ values: { image: '', name: '', symbol: '', description: '', website: '', x: '', discord: '', telegram: '' } }}
          onSubmit={onSubmit}
        >
          {props => (
            <Form>
              <VStack gap={{ base: '20px', lg: '8px' }} w="100%">
                <Stack flexDir={{ base: 'column', lg: 'row' }} gap="20px" justify="flex-start" w="100%" align="flex-start">
                  <Field name="image">
                    {({ field, form }) => (
                      <FormControl isRequired w={{ base: '202px', lg: '162px' }}>
                        <Label requiredIndicator={<Required />}>Image</Label>
                        <FormValueGroup isInvalid={false}>
                          <Upload
                            ref={uploadRef}
                            width={{ base: '202px', lg: '162px' }}
                            height={{ base: '202px', lg: '162px' }}
                            fileSize="1MB"
                            {...formInputStyle}
                            p="0px"
                            accept="image/png, image/jpeg"
                            field={field}
                            form={form}
                            onSuccess={() => {
                              toast({
                                position: 'top-right',
                                render: () => {
                                  return <UploadLimitToast title="Image uploaded successfully" onClose={() => toast.closeAll()} status="success" />
                                }
                              })
                            }}
                            onError={(error: string) => {
                              console.log(error, 'error')
                              const title = error?.includes('file size')
                                ? 'Image must be less than 1MB'
                                : error.toLowerCase().includes('inappropriate')
                                  ? 'Image security check failed'
                                  : 'Image upload failed'
                              toast({
                                position: 'top-right',
                                render: () => {
                                  return <UploadLimitToast title={title} onClose={() => toast.closeAll()} status="error" />
                                }
                              })
                            }}
                            onChange={handleImageChange}
                          >
                            <VStack h="100%" justify="center" gap="0px">
                              <Icon xlinkHref="#icon-icon_img" svgFill="primary_gray" svgHover="primary_gray" mb="8px" />
                              <Text lineHeight="20px" h="20px" color="primary_gray" fontSize="12px">
                                JPEG/PNG
                              </Text>
                              <Text lineHeight="20px" h="20px" color="primary_gray" fontSize="12px">
                                Less Than 1MB
                              </Text>
                            </VStack>
                          </Upload>
                        </FormValueGroup>
                      </FormControl>
                    )}
                  </Field>
                  <VStack flex="1" w={{ base: '100%', lg: 'calc(100% - 182px)' }} justify="space-between" gap={{ base: '20px', lg: '6px' }}>
                    <Field
                      name="name"
                      validate={(value?: string) => {
                        if (value && typeof value === 'string') {
                          if (!ExcludeCNCharRegex.test(value)) {
                            return 'Token name cannot contain Chinese characters'
                          }
                          if (value?.trim?.()?.length > 20) {
                            return 'Token name cannot be more than 20 characters'
                          }
                          if (value.length > 0 && value?.trim?.()?.length === 0) {
                            return 'Invalid characters'
                          }
                          if (!ExcludeSpecialCharRegex.test(value)) {
                            return 'Token name cannot enter symbols'
                          }
                          if ((nameRef?.current as unknown as any)?.hasAttribute('data-focus')) {
                            if (value?.trim?.() === (props as unknown as any).values.symbol?.trim?.()) {
                              return 'Token name and token symbol must be different'
                            }
                            if (value?.trim?.() === (props as unknown as any).values.description?.trim?.()) {
                              return 'Token name and token description must be different'
                            }
                          }
                        }
                      }}
                      flex="1"
                    >
                      {({ field, form }) => (
                        <FormControl ref={nameRef} isInvalid={form.errors.name && form.touched.name} isRequired>
                          <Label requiredIndicator={<Required />}>Token Name</Label>
                          <FormValueGroup message={form.errors.name} isInvalid={form.errors.name && form.touched.name}>
                            <Input
                              {...field}
                              placeholder="Token Name"
                              {...formInputStyle}
                              _focusVisible={{
                                borderColor: 'primary',
                                boxShadow: `0px 1px 0px 0px primary`
                              }}
                              {...(form.errors.name && form.touched.name
                                ? { borderColor: 'input_error_border', boxShadow: 'input_error_border 0px 0px 0px 1px' }
                                : {})}
                            />
                          </FormValueGroup>
                        </FormControl>
                      )}
                    </Field>
                    <Field
                      name="symbol"
                      validate={(value?: string) => {
                        if (value && typeof value === 'string') {
                          if (!ExcludeCNCharRegex.test(value)) {
                            return 'Token symbol cannot contain Chinese characters'
                          }
                          if (value?.trim?.()?.length > 10) {
                            return 'Token symbol cannot be more than 10 characters'
                          }
                          if (value.length > 0 && value?.trim?.()?.length === 0) {
                            return 'Invalid characters'
                          }
                          if (!SymbolExcludeSpecialCharRegex.test(value)) {
                            return 'Token symbol cannot enter symbols'
                          }
                          if (!SymbolLimitRegex.test(value)) {
                            return 'Must start with uppercase, then alphanumerics or underscores'
                          }
                          if ((symbolRef?.current as unknown as any)?.hasAttribute('data-focus')) {
                            if (value?.trim?.() === (props as unknown as any).values.name?.trim?.()) {
                              return 'Token symbol and token name must be different'
                            }
                            if (value?.trim?.() === (props as unknown as any).values.description?.trim?.()) {
                              return 'Token symbol and token description must be different'
                            }
                          }
                        }
                      }}
                      flex="1"
                    >
                      {({ field, form }) => (
                        <FormControl ref={symbolRef} isInvalid={form.errors.symbol && form.touched.symbol} isRequired>
                          <Label requiredIndicator={<Required />}>Token Symbol</Label>
                          <FormValueGroup message={form.errors.symbol} isInvalid={form.errors.symbol && form.touched.symbol}>
                            <Input
                              ref={symbolInputRef}
                              {...field}
                              onChange={e => {
                                if (BlankSpaceRegex.test(e.target.value)) {
                                  e.target.value = e.target.value.replace(/\s+/g, '')
                                }
                                field.onChange(e)
                              }}
                              placeholder="Ticker"
                              {...formInputStyle}
                              _focusVisible={{
                                borderColor: 'primary',
                                boxShadow: `0px 1px 0px 0px primary`
                              }}
                              {...(form.errors.symbol && form.touched.symbol
                                ? { borderColor: 'input_error_border', boxShadow: 'input_error_border 0px 0px 0px 1px' }
                                : {})}
                            />
                          </FormValueGroup>
                        </FormControl>
                      )}
                    </Field>
                  </VStack>
                </Stack>

                <Field
                  name="description"
                  validate={excludeCharValidate('Description', value => {
                    if (value && typeof value === 'string' && value.length > 0 && value?.trim?.()?.length === 0) {
                      return 'Invalid characters'
                    }
                    if ((descriptionRef.current as unknown as any)?.hasAttribute('data-focus')) {
                      if (value?.trim?.() === (props as unknown as any).values.name?.trim?.()) {
                        return 'Token description and token name must be different'
                      }
                      if (value?.trim?.() === (props as unknown as any).values.symbol?.trim?.()) {
                        return 'Token description and token symbol must be different'
                      }
                    }
                  })}
                >
                  {({ field, form }) => (
                    <FormControl ref={descriptionRef} isInvalid={form.errors.description && form.touched.description} isRequired>
                      <HStack w="100%" justify="space-between">
                        <Label requiredIndicator={<Required />}>Token Description</Label>
                        <Text>{`${((form.values?.description as string) || '')?.trim?.()?.length}/256`}</Text>
                      </HStack>
                      <FormValueGroup message={form.errors.description} isInvalid={form.errors.description && form.touched.description}>
                        <Textarea
                          {...field}
                          placeholder="Description"
                          {...formInputStyle}
                          border="none"
                          maxLength={256}
                          _placeholder={{ color: 'primary_gray', fontFamily: 'Inter, sans-serif' }}
                        />
                      </FormValueGroup>
                    </FormControl>
                  )}
                </Field>

                <VStack gap="20px" w="100%">
                  <Field
                    name="website"
                    validate={excludeCharValidate('Url', value => {
                      if (!WebSiteUrlRegex.test(value)) {
                        return 'URL is invalid'
                      }
                      if (value.length > 0 && value?.trim?.()?.length === 0) {
                        return 'Invalid characters'
                      }
                      if (
                        (websiteRef.current as unknown as any)?.hasAttribute('data-focus') &&
                        (value?.trim?.() === (props as unknown as any).values.x?.trim?.() ||
                          value?.trim?.() === (props as unknown as any).values.discord?.trim?.() ||
                          value?.trim?.() === (props as unknown as any).values.telegram?.trim?.())
                      ) {
                        return 'URL cannot enter the same link'
                      }
                    })}
                  >
                    {({ field, form }) => (
                      <FormControl isInvalid={form.errors.website && form.touched.website} ref={websiteRef}>
                        <Label>Website</Label>
                        <FormValueGroup message={form.errors.website} isInvalid={form.errors.website && form.touched.website} placeholder={false}>
                          <FormInput
                            icon="#icon-icon_language"
                            placeholder="Website"
                            field={field}
                            isInvalid={form.errors.website && form.touched.website}
                          />
                        </FormValueGroup>
                      </FormControl>
                    )}
                  </Field>
                  <Field
                    name="x"
                    validate={excludeCharValidate('Url', value => {
                      if (!WebSiteUrlRegex.test(value)) {
                        return 'URL is invalid'
                      }
                      if (!XUrlRegex.test(value)) {
                        return 'URL link type error'
                      }
                      if (value.length > 0 && value?.trim?.()?.length === 0) {
                        return 'Invalid characters'
                      }
                      if (
                        (xUrlRef.current as unknown as any)?.hasAttribute('data-focus') &&
                        value?.trim?.() === (props as unknown as any).values.website?.trim?.()
                      ) {
                        return 'URL cannot enter the same link'
                      }
                    })}
                  >
                    {({ field, form }) => (
                      <FormControl isInvalid={form.errors.x && form.touched.x} ref={xUrlRef}>
                        <Label>X(Twitter)</Label>
                        <FormValueGroup message={form.errors.x} isInvalid={form.errors.x && form.touched.x} placeholder={false}>
                          <FormInput icon="#icon-icon_twitter" placeholder="X(Twitter)" field={field} isInvalid={form.errors.x && form.touched.x} />
                        </FormValueGroup>
                      </FormControl>
                    )}
                  </Field>
                  <Field
                    name="discord"
                    validate={excludeCharValidate('Url', value => {
                      if (!WebSiteUrlRegex.test(value)) {
                        return 'URL is invalid'
                      }
                      if (!DiscordRegex.test(value)) {
                        return 'URL link type error'
                      }
                      if (value.length > 0 && value?.trim?.()?.length === 0) {
                        return 'Invalid characters'
                      }
                      if (
                        (discordRef.current as unknown as any)?.hasAttribute('data-focus') &&
                        value?.trim?.() === (props as unknown as any).values.website?.trim?.()
                      ) {
                        return 'URL cannot enter the same link'
                      }
                    })}
                  >
                    {({ field, form }) => (
                      <FormControl isInvalid={form.errors.discord && form.touched.discord} ref={discordRef}>
                        <Label>Discord</Label>
                        <FormValueGroup message={form.errors.discord} isInvalid={form.errors.discord && form.touched.discord} placeholder={false}>
                          <FormInput
                            icon="#icon-icon_discord"
                            placeholder="Discord"
                            field={field}
                            isInvalid={form.errors.discord && form.touched.discord}
                          />
                        </FormValueGroup>
                      </FormControl>
                    )}
                  </Field>
                  <Field
                    name="telegram"
                    validate={excludeCharValidate('Url', value => {
                      if (!WebSiteUrlRegex.test(value)) {
                        return 'URL is invalid'
                      }
                      if (!TelegramRegex.test(value)) {
                        return 'URL link type error'
                      }
                      if (value.length > 0 && value?.trim?.()?.length === 0) {
                        return 'Invalid characters'
                      }
                      if (
                        (telegramRef.current as unknown as any)?.hasAttribute('data-focus') &&
                        value?.trim?.() === (props as unknown as any).values.website?.trim?.()
                      ) {
                        return 'URL cannot enter the same link'
                      }
                    })}
                  >
                    {({ field, form }) => (
                      <FormControl isInvalid={form.errors.telegram && form.touched.telegram} ref={telegramRef}>
                        <Label>Telegram</Label>
                        <FormValueGroup message={form.errors.telegram} isInvalid={form.errors.telegram && form.touched.telegram} placeholder={false}>
                          <FormInput
                            icon="#icon-icon_telegram1"
                            placeholder="Telegram"
                            field={field}
                            isInvalid={form.errors.telegram && form.touched.telegram}
                          />
                        </FormValueGroup>
                      </FormControl>
                    )}
                  </Field>
                  <VStack gap={{ base: '24px', lg: '20px' }}>
                    <HStack w="100%" justify="space-between" margin={{ base: '12px 0px', lg: '0px' }}>
                      <Text>Deployment Fee</Text>
                      <SelectTab
                        type="outlineTab"
                        tabList={(feeList || [])?.map(item => ({
                          label: `${item?.amount_display} ${item?.symbol}`,
                          imgInfo: { src: item?.logo_url || '', w: '20px', h: '20px', borderRadius: '50%' }
                        }))}
                        wrapStyle={{
                          h: '36px',
                          p: '4px'
                        }}
                        itemStyle={{
                          fontSize: '14px',
                          gap: '4px',
                          p: { base: '0 4px', lg: '0 20px' },
                          borderRadius: '6px'
                        }}
                        currentTab={params?.fee}
                        handleChangeTab={handleFeeChange}
                      />
                    </HStack>

                    {!currentAccount ? (
                      <Button w="100%" fontSize="18px" fontWeight="600" borderRadius="16px" h="52px" onClick={() => onWalletModal(true)}>
                        Connect Wallet
                      </Button>
                    ) : (
                      <Button
                        w="100%"
                        fontSize="18px"
                        fontWeight="600"
                        type="submit"
                        borderRadius="16px"
                        h="52px"
                        isLoading={loading}
                        disabled={
                          !(
                            (props as unknown as any)?.values?.image &&
                            (props as unknown as any)?.values.image.length &&
                            (props as unknown as any)?.values.image?.[0]?.fileUrl &&
                            (props as unknown as any)?.values?.name?.trim?.() &&
                            (props as unknown as any)?.values?.symbol?.trim?.() &&
                            (props as unknown as any)?.values?.description?.trim?.()
                          ) ||
                          isInvalidBalance() ||
                          loading ||
                          Object.values((props as unknown as any).errors).length > 0
                        }
                      >
                        {isInvalidBalance() ? `Insufficient ${params?.fee?.split(' ')[1]} balance` : 'Create'}
                      </Button>
                    )}

                    <Box p={{ base: '16px 12px', lg: '20px 28px' }} borderRadius="12px" bg="primary_yellow_opacity.10" w="100%">
                      <Text color="primary_yellow" fontSize="14px" lineHeight="20px">
                        Tokens are NOT publicly tradeable/transferable before they escape the bonding curve.
                      </Text>
                    </Box>
                  </VStack>
                </VStack>
              </VStack>
            </Form>
          )}
        </Formik>
      </Box>

      {isOpenModal && createTokenModelOptions && (
        <CreateTokenModel
          options={createTokenModelOptions}
          isOpen={isOpenModal}
          onClose={() => {
            setIsOpenModal(false)
          }}
        />
      )}
    </VStack>
  )
}

export default Create
