import { calcNumber } from '@/utils'
import { SingleCoinImage } from '@cetus/ui-kit'
import { VariantType } from '@cetus/ui-kit/src/components/Icon'
import { d } from '@cetus/utils'
import { Flex, FlexProps, ImageProps, Text } from '@chakra-ui/react'

type iconInfo = {
  xlinkHref: string
  svgW?: string
  svgH?: string
  variant?: VariantType
  onClick?: (e: any) => void
}
interface imgInfo extends ImageProps {
  onClick?: (e: any) => void
}

export type Tab = {
  label: string
  imgInfo?: imgInfo
  beforeIcon?: iconInfo
  afterIcon?: iconInfo
  num?: string
}

interface SelectTabProps extends FlexProps {
  type: 'outlineTab' | 'borderTab'
  currentTab: string | Tab
  tabList: Tab[]
  isActive?: (currentTab: string | Tab) => boolean
  handleChangeTab: (item: any) => void
  wrapStyle?: FlexProps
  itemStyle?: FlexProps
}
export default function SelectTab(props: SelectTabProps) {
  const {
    type,
    tabList,
    currentTab,
    isActive,
    handleChangeTab,
    wrapStyle = { h: '60px', p: '8px' },
    itemStyle = { fontSize: '14px' },
    ...rest
  } = props
  return (
    <>
      {type === 'outlineTab' && (
        <Flex bg="bg_secondary" borderRadius="12px" border="1px solid" borderColor="border" {...wrapStyle}>
          {tabList?.map(tab => {
            return (
              <Flex
                borderRadius="4px"
                align="center"
                justify="center"
                key={tab.label}
                cursor="pointer"
                bg={(isActive ? isActive(currentTab) : currentTab == tab.label) ? 'card_bg' : 'none'}
                onClick={() => handleChangeTab(tab)}
                {...itemStyle}
              >
                {tab.imgInfo && <SingleCoinImage {...tab.imgInfo} imageUrl={tab.imgInfo.src} />}

                <Text
                  fontSize={itemStyle.fontSize}
                  color={(isActive ? isActive(currentTab) : currentTab == tab.label) ? 'primary' : 'primary_gray'}
                  _hover={{ color: 'primary' }}
                >
                  {tab.label}
                </Text>
              </Flex>
            )
          })}
        </Flex>
      )}
      {type === 'borderTab' && (
        <Flex borderRadius="12px" bg="bg_secondary" border="1px solid" borderColor="border" {...wrapStyle}>
          {tabList?.map(tab => {
            return (
              <Flex align="center" justify="center" key={tab.label} cursor="pointer" onClick={() => handleChangeTab(tab)} {...itemStyle} {...rest}>
                {tab.imgInfo && <SingleCoinImage {...tab.imgInfo} imageUrl={tab.imgInfo.src} mr="8px" />}
                <Text
                  color={(isActive ? isActive(currentTab) : currentTab == tab.label) ? 'primary' : 'primary_gray'}
                  fontSize={itemStyle.fontSize}
                  h={itemStyle.fontSize}
                  lineHeight={itemStyle.fontSize}
                  position="relative"
                  sx={Object.assign(
                    {
                      _hover: {
                        color: 'primary'
                      },
                      _before: (isActive ? isActive(currentTab) : currentTab == tab.label)
                        ? {
                            content: "''",
                            width: '20px',
                            height: '2px',
                            background: 'primary',
                            position: 'absolute',
                            left: 'calc(50% - 10px)',
                            bottom:
                              -d(calcNumber(wrapStyle.h as string | number))
                                .minus(calcNumber((itemStyle.fontSize || '14px') as string | number))
                                .div(2)
                                .toString() + 'px'
                          }
                        : {}
                    },
                    itemStyle?.sx || {}
                  )}
                >
                  {tab.label}
                </Text>
              </Flex>
            )
          })}
        </Flex>
      )}
    </>
  )
}
