import { Center, CenterProps, Image } from '@chakra-ui/react'
import { keyframes } from '@emotion/react'
import GhostLoading from './assets/images/ghost_loading.png'
import PrimaryLoading from './assets/images/loading.png'

const spin = keyframes`
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
`

interface SpinnerProps {
  wrapStyle?: CenterProps
  size?: string | number
  variant?: 'primary' | 'ghost'
}

const imageMap = {
  primary: PrimaryLoading,
  ghost: GhostLoading
}

export default function Spinner({ size = '20px', variant = 'primary', wrapStyle = {} }: SpinnerProps) {
  return (
    <Center w="100%" h="100%" {...wrapStyle}>
      <Image
        boxSize={size} // 设置图标大小
        src={imageMap[variant]}
        alt="Loading"
        animation={`${spin} 1s linear infinite`} // 设置旋转动画
      />
    </Center>
  )
}
