import { Center, HTMLChakraProps } from '@chakra-ui/react'
import { useMemo } from 'react'

export type VariantType = 'solid' | 'gray' | 'rectangle' | '' | 'error' | 'warning' | 'primary'
export interface IconProps extends HTMLChakraProps<'div'> {
  xlinkHref: string
  svgW?: string
  svgH?: string
  boxW?: string
  boxH?: string
  notAllowed?: boolean
  svgHover?: string
  svgFill?: string
  variant?: VariantType
  onClick?: (e: any) => void
}

/**
 *
 * @param props
 * variant
 *  空： 默认，不带背景，hover默认白色---cetus
 *  solid: 带背景，正方形
 *  gray: 不带背景，灰色系 hover白色
 *  primary: 不带背景，灰色hover主题色
 *  warning: warning icon
 *  error: error icon
 *  rectangle: 带背景，长方形
 *
 * @returns
 */
export default function Icon(props: IconProps) {
  const { xlinkHref, fontSize, svgW, svgH, boxW, boxH, variant, svgHover, svgFill, onClick, notAllowed, ...rest } = props

  const style = useMemo(() => {
    const styles = {
      base: {
        box: {
          w: boxW || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover: {
            svg: {
              fill: svgHover || 'text_caption'
            }
          }
        },
        svg: {
          fill: `var(--chakra-colors-${svgFill || 'text_paragraph'})`,
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      gray: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover: {
            svg: {
              fill: 'text_caption'
            }
          }
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      primary: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover: {
            svg: {
              fill: 'primary'
            }
          }
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      warning: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover: {
            svg: {
              fill: 'primary_yellow'
            }
          }
        },
        svg: {
          fill: 'var(--chakra-colors-primary_yellow)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      error: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover: {
            svg: {
              fill: 'primary_red'
            }
          }
        },
        svg: {
          fill: 'var(--chakra-colors-primary_red)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      solid: {
        box: {
          bg: 'checked_bg',
          w: boxW || fontSize || '24px',
          h: boxH || fontSize || '24px',
          borderRadius: '4px',
          _hover: {
            svg: {
              fill: svgHover || 'text_caption'
            }
          }
        },
        svg: {
          fill: `var(--chakra-colors-${svgFill || 'text_paragraph'})`,
          width: svgW || fontSize || '16px',
          height: svgH || fontSize || '16px'
        }
      },
      rectangle: {
        box: {
          bg: 'card_bg',
          w: boxW || fontSize || '28px',
          h: boxH || fontSize || '20px',
          borderRadius: '8px',
          _hover: {
            svg: {
              fill: 'primary'
            }
          }
        },
        svg: {
          fill: 'var(--chakra-colors-primary)',
          width: svgW || fontSize || '16px',
          height: svgH || fontSize || '16px'
        }
      }
    }

    return !variant ? styles['base'] : styles[variant]
  }, [variant, svgW, svgH, boxW, boxH, fontSize, svgFill, svgHover])

  return (
    <Center cursor={notAllowed ? 'not-allowed' : 'pointer'} {...style.box} {...rest} onClick={onClick}>
      <svg aria-hidden="true" {...style.svg}>
        <use xlinkHref={xlinkHref} />
      </svg>
    </Center>
  )
}
