import { CreateTokenModelOptions } from '@/type/pump'
import { PumpUtils } from '@/utils/pumpUtils'
import { useAccountBalance } from '@cetus/hooks/src/useAccountBalance'
import useExplorer from '@cetus/hooks/src/useExplorer'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import { useSigner } from '@cetus/hooks/src/useSigner'
import useTransaction from '@cetus/hooks/src/useTransaction'
import { useAccountStore } from '@cetus/stores'
import { BalanceChanges, CommonTypeInfo, ToastType, TransactionStatusType } from '@cetus/types'
import { formatNumber, fromDecimalsAmountFix, getBalanceChanges, isUserRejectedError, sleepTime } from '@cetus/utils'
import { d, fromDecimalsAmount, getPackagerConfigs } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { CalculateSwapAmountResult, PublishTokenOptions, StartBondingCurveOptions } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SUI_TYPE_ARG } from '@mysten/sui/utils'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import useGlobalToast from '../../../../hooks/src/useGlobalToast'
import useTransactionModal from '../../../../hooks/src/useTransactionModal'

export function useCreateToken() {
  const { currentAccount } = useAccountStore()
  const { signAndExecuteTransactionBlock } = useSigner()
  const { pumpSdk, clmmSdk } = useInitSDK()
  const { getExplorerUrl } = useExplorer()

  const { getTransactionStatus } = useTransaction()

  const [isOpenModal, setIsOpenModal] = useState<boolean>(false)
  const [createTokenModelOptions, setCreateTokenModelOptions] = useState<CreateTokenModelOptions | undefined>()
  const { fetchAccountBalance } = useAccountBalance()
  const navigate = useNavigate()

  const [hasCreated, setHasCreated] = useState<boolean>(false)
  const { failedTsToast, submittedTsToast, successTsToast, closeToast } = useGlobalToast()
  const { transactionSuccess } = useTransactionModal()

  const handleSubmitPublishToken = async (options: PublishTokenOptions) => {
    setHasCreated(false)
    if (currentAccount === undefined) {
      return
    }
    const { tokenTicker, tokenName, fee, sig } = options

    // 第一步发布token
    const tokenInfo = await handlePublishTokenStepOne(options)

    if (tokenInfo === undefined) {
      return
    }

    // 第二步 购买
    const createOptions: CreateTokenModelOptions = {
      tokenTicker,
      tokenName,
      stepIndex: 2,
      showIndex: 2,
      status: 'confirmation',
      deploymentFee: fee,
      onSkipClick: async () => {
        // 只设置fee
        await handlePublishTokenStepTwo(createOptions, sig)
      },

      onBuyClick: async (swapResult: CalculateSwapAmountResult) => {
        // 设置fee+ 购买
        await handlePublishTokenStepTwo(createOptions, sig, swapResult)
      }
    }

    console.log('🚀 ~ file: useCreateToken.ts:52 ~ handleSubmitPublishToken ~ tokenInfo:', tokenInfo)

    // 展示第二步购买弹窗
    createOptions.token = tokenInfo
    setCreateTokenModelOptions({ ...createOptions, deploymentFee: fee })
    setIsOpenModal(true)
  }

  /**
   * 第二步
   * @param createOptions
   * @param fee
   * @param pay_amount
   * @param amount_limit
   * @param coinInfo
   */
  const handlePublishTokenStepTwo = async (createOptions: CreateTokenModelOptions, sig: string, swapResult?: CalculateSwapAmountResult) => {
    console.log('🚀 ~ file: useCreateToken.ts:96 ~ handlePublishTokenStepTwo ~ createOptions:', createOptions)

    createOptions.stepIndex = 1
    setCreateTokenModelOptions({ ...createOptions })

    const isBuy = swapResult && d(swapResult.amount_in || 0).gt(0)

    const { clmm_pool } = clmmSdk.sdkOptions
    const { global_config_id, pools_id } = getPackagerConfigs(clmm_pool)

    const { bonding_curve_id, start_cap_id, coinInfo } = createOptions.token!
    const { coin_type } = coinInfo

    let buyOptions = undefined

    if (isBuy && swapResult) {
      buyOptions = {
        pay_coin_type: SUI_TYPE_ARG,
        swap_result: swapResult
      }
    }

    const startBondingOptions: StartBondingCurveOptions = {
      bonding_curve_id,
      start_cap_id,
      fee_amount: createOptions.deploymentFee.fee_amount,
      fee_coin_type: createOptions.deploymentFee.fee_coin_type,
      clmm_pools_id: pools_id,
      clmm_config_id: global_config_id,
      token_coin_type: coin_type,
      buy_Options: buyOptions,
      sig
    }

    console.log('🚀 ~ file: useCreateToken.ts:77 ~ handleSubmitPublishToken ~ startBondingOptions:', startBondingOptions)

    try {
      const payload = await pumpSdk.pumpModule.buildStartBondingCurvePayload(startBondingOptions)
      payload.setGasBudget(100000000)
      console.log('🚀 ~ file: useCreateToken.ts:82 ~ onSkipClick: ~ tx:', payload)

      const result = await signAndExecuteTransactionBlock(payload, false)

      console.log('🚀 ~ file: useCreateToken.ts:142 ~ handlePublishTokenStepTwo ~ result:', result)
      await sleepTime(2000)
      const res = await getTransactionStatus(result.digest)

      console.log('🚀 ~ file: useCreateToken.ts:145 ~ handlePublishTokenStepTwo ~ res:', res)

      // 失败
      if (!res || res.effects?.status.status === 'failure') {
        createOptions.status = 'rejected'
        setCreateTokenModelOptions({ ...createOptions })
        showFailedTsToast(undefined)
        return
      }
      // 成功
      const info: ToastType = {
        link: getExplorerUrl(result.digest, 'tx'),
        getShowInfo: (status: TransactionStatusType, balanceChanges?: Record<string, BalanceChanges>): CommonTypeInfo => {
          const descriptionText = isBuy
            ? `Create and Buy ${formatNumber(fromDecimalsAmount(swapResult?.amount_out, coinInfo?.decimals || 9))} ${createOptions.tokenTicker} successful`
            : 'Create token successful'
          const info: CommonTypeInfo = {
            iconUrl: coinInfo?.logo_url,
            toastTitleText: `${coinInfo?.name} (${coinInfo?.symbol})`,
            toastDescriptionContent: descriptionText,
            modalTitleText: `Create ${coinInfo?.symbol}`,
            modalDescriptionText: descriptionText,
            modalConfirmButtonText: ['Trade Now'],
            modalConfirmButtonClick: (_: number) => {
              navigate(`/trade/${coinInfo.coin_type}`)
            }
          }

          if (status === 'submitted') {
            info.toastDescriptionContent = undefined
          }

          if (balanceChanges) {
            if (isBuy) {
              let amount = fromDecimalsAmountFix(swapResult?.amount_out, 9)
              amount = getBalanceChanges(balanceChanges, coinInfo) || amount
              const descriptionText = `Create and Buy ${formatNumber(amount)} ${createOptions.tokenTicker} successful`
              info.toastDescriptionContent = descriptionText
              info.modalDescriptionText = descriptionText
            }
          }

          return info
        }
      }

      const transactionId = submittedTsToast(info)
      await sleepTime(2000)
      closeToast(transactionId)
      if (result.errors) {
        createOptions.status = 'rejected'
        showFailedTsToast(result.errors)
        setCreateTokenModelOptions({ ...createOptions })
      } else {
        setHasCreated(true)
        // 成功
        setIsOpenModal(false)

        transactionSuccess(info)

        successTsToast(info)

        fetchAccountBalance()
      }
    } catch (error) {
      console.log('🚀 ~ file: useCreateToken.ts:83 ~ onSkipClick: ~ error:', error, isUserRejectedError(error))
      if (isUserRejectedError(error)) {
        // 用户拒绝回到第二步
        createOptions.stepIndex = 2
        setCreateTokenModelOptions({ ...createOptions })
      } else {
        createOptions.status = 'rejected'
        setCreateTokenModelOptions({ ...createOptions })
        showFailedTsToast(error)
      }
    }
  }

  /**
   * 第一步
   * @param options
   * @returns
   */
  const handlePublishTokenStepOne = async (options: PublishTokenOptions) => {
    if (currentAccount === undefined) {
      return
    }
    const { tokenTicker, tokenName, fee } = options

    const payload = await pumpSdk.pumpModule.buildPublishTokenPayload(options)
    payload.setGasBudget(100000000)
    console.log('🚀 ~ file: useCreateToken.ts:201 ~ handlePublishTokenStepOne ~ payload:', payload)

    // 展示第一步待确认弹窗
    const createOptions: CreateTokenModelOptions = {
      tokenTicker,
      tokenName,
      stepIndex: 1,
      showIndex: 1,
      status: 'confirmation',
      deploymentFee: fee
    }

    setCreateTokenModelOptions({ ...createOptions })
    setIsOpenModal(true)

    try {
      const result = await signAndExecuteTransactionBlock(payload, true)

      console.log('🚀 ~ file: useCreateToken.ts:255 ~ handlePublishTokenStepOne ~ result:', result)
      await sleepTime(2000)
      const res = await getTransactionStatus(result.digest, 0)

      console.log('🚀 ~ file: useCreateToken.ts:260 ~ handlePublishTokenStepOne ~ res:', res)

      // 失败
      if (!res || res.effects?.status.status === 'failure') {
        createOptions.status = 'rejected'
        setCreateTokenModelOptions({ ...createOptions })
        showFailedTsToast(undefined)
        return
      }

      //获取到tx  解析数据
      const tokenInfo = PumpUtils.parseCreateBondingCurveEvent(result)

      console.log('🚀 ~ file: useCreateToken.ts:228 ~ handlePublishTokenStepOne ~ tokenInfo:', tokenInfo)

      return tokenInfo
    } catch (error) {
      console.log('🚀 ~ file: useCreateToken.ts:118 ~ useCreateToken ~ error:', error)
      createOptions.status = 'rejected'
      setCreateTokenModelOptions({ ...createOptions })

      showFailedTsToast(error)
    }

    return undefined
  }

  const showFailedTsToast = (error: any) => {
    const isUserRejected = isUserRejectedError(error)
    const info: ToastType = {
      getShowInfo: (_: TransactionStatusType): CommonTypeInfo => {
        const info: CommonTypeInfo = {
          toastDescriptionContent: isUserRejected ? 'User Rejected the request' : undefined
        }
        return info
      }
    }

    failedTsToast(info)
  }

  return {
    hasCreated,
    handleSubmitPublishToken,
    isOpenModal,
    setIsOpenModal,
    createTokenModelOptions
  }
}
