import { Center, Flex, HTMLChakraProps, Image } from '@chakra-ui/react'
import { useMemo } from 'react'
import PlaceholderToken from './assets/images/placeholder-token@2x.png'
import IconTipsTriangle from './assets/images/token-warning@2x.png'
interface SingleCoinImageProps extends HTMLChakraProps<'div'> {
  imageUrl?: string
  variant?: 'border' | ''
  showTag?: boolean
  showTagWidth?: string
  w?: string
  showTagHeight?: string
  borderColor?: string
  h?: string
  p?: string
}

export default function SingleCoinImage(props: SingleCoinImageProps) {
  const { variant, imageUrl, w, h, p, showTag = false, showTagWidth, showTagHeight, borderColor, ...rest } = props
  const style = useMemo(() => {
    const styles = {
      default: {
        box: {
          border: 'none',
          w: w || '32px',
          h: h || '32px'
        }
      },
      border: {
        box: {
          bg: 'background',
          border: '1px',
          borderColor: borderColor || 'border',
          borderRadius: '100%',
          w: w || '46px',
          h: w || '46px',
          p: p || '5px'
        }
      }
    }
    return variant ? styles[variant] : styles['default']
  }, [variant, w, borderColor, p])

  return (
    <Flex display="flex" position="relative">
      <Center {...style.box} {...rest}>
        <Image src={imageUrl} fallbackSrc={PlaceholderToken} borderRadius="100%" w="100%" h="100%" />
      </Center>
      {showTag && (
        <Image
          src={IconTipsTriangle}
          fallbackSrc={PlaceholderToken}
          w={showTagWidth ? showTagWidth : '16px'}
          h={showTagHeight ? showTagHeight : '16px'}
          right={variant === 'border' ? '1px' : '-3px'}
          style={{ position: 'absolute', bottom: '0px' }}
        />
      )}
    </Flex>
  )
}
