export const formatPercentage = (
  value: string | number | undefined,
  decimal: number = 2,
  hidelt: boolean = false,
  notDisplayZero: boolean = false // true 为0时则展示为<0.01
) => {
  if (value === undefined) return '--'
  if (d(value).equals(0)) {
    if (notDisplayZero) {
      return `< ${Math.pow(10, -decimal)}%`
    }
    return '0%'
  }

  if (!hidelt) {
    if (Number(value) >= 0 && Number(value) <= Math.pow(10, -decimal)) {
      return `<${Math.pow(10, -decimal)}%`
    }
    if (Number(value) < 0 && Number(value) * -1 <= Math.pow(10, -decimal)) {
      return `- < ${Math.pow(10, -decimal)}%`
    }
  }
  return `${fixDown(value, decimal)}%`
}

export const formatPercentageGt0And100 = (value: string | number | undefined, decimal: number = 2) => {
  if (typeof value === 'undefined' || value === 'undefined' || (value !== 0 && !value)) return '--'
  if (d(value).equals(0)) {
    return `< ${Math.pow(10, -decimal)}%`
  }

  if (d(value).gt(100)) {
    return '> 100%'
  }

  const num = fixDown(value, decimal)
  return `${num}%`
}

/**
 *
 * @param value 需处理的数值
 * @param noComma 不展示千位符
 *
 * 规则：
 *  1. 整数>=9位时，可不展示小数
 *  2. 9>整数>=4位时，可最多展示2位小数
 *  3. 4>整数>=1位有效整数时（有效整数只不为0数字），可最多展示4位小数
 *  整数为0时，当小数中
 *  4. 小数位可展示除0外6位有效数字，例如0.041427588666038278展示为0.0414275
 *  5. 第6位依然为0则在第9位小数后+1位小数
 *  6. 第7位依然为0则在第9位小数后+2位小数
 *  7. 第8位依然为0则在第9位小数后+3位小数
 *  8. 第9位依然为0则在第9位小数后+4位小数
 *  ...
 *  最多展示到18位小数 (5,6,7,8暂不实现)
 *
 */
export const formatNumber = (
  value: string | number | undefined,
  decimal?: number,
  noComma?: boolean,
  rounding: Decimal.Rounding = Decimal.ROUND_HALF_DOWN
) => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  if (d(value).equals(0)) return '0'

  if (decimal !== undefined) {
    const result = fixNumber(value, decimal, rounding)
    if (!d(result).equals(0)) {
      return noComma ? result : addComma(result)
    }
  }

  const str = d(value).toString()
  const arr = str.split('.')
  const integerPart = arr[0]
  const decimalPart = arr[1]
  let result
  if (d(integerPart).gt(0)) {
    if (!decimalPart || d(integerPart.length).gte(9)) {
      result = fixNumber(str, 0, rounding)
    } else if (d(integerPart.length).gte(4)) {
      result = fixNumber(str, 2, rounding)
      // } else if (d(integerPart.length).gte(1)) {
    } else {
      result = fixNumber(str, 4, rounding)
    }
  } else {
    const r = fixNumber(str, 6, rounding)
    const gtZeroIndex = getGtZeroIndex(decimalPart)
    if (gtZeroIndex < 6) {
      result = fixNumber(str, gtZeroIndex + 6, rounding)
    } else {
      if (gtZeroIndex > 30) return '0'
      result = fixNumber(str, 9 + (gtZeroIndex - 6), rounding)
    }
  }

  return noComma || d(integerPart).lt(1) ? result : addComma(result)
}
