export const formatPerpsNumber = (value: string | number | undefined, noComma?: boolean) => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  if (d(value).equals(0)) return '0'

  const str = d(value).toString()
  const arr = str.split('.')
  const integerPart = arr[0]
  const decimalPart = arr[1]
  let result
  const gtZeroIndex = getGtZeroIndex(decimalPart)
  if (gtZeroIndex < 3) {
    result = fixRounding(str, 2)
  } else {
    if (gtZeroIndex < 5) {
      result = fixRounding(str, 4)
    } else {
      result = str
    }
  }
  return noComma || d(integerPart).lt(1) ? result : addComma(result)
}

export const formatNumberWithLtMinPrecision = (value: string | number | undefined, decimal: number = 2, noComma?: boolean) => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  if (d(value).equals(0)) return '0'

  if (d(value).lt(Math.pow(10, -decimal))) {
    return '< 0.01'
  }
  return formatNumber(value, decimal, noComma)
}

export const formatNumberWithKMB = (value: string | number | undefined, decimal: number = 2) => {
  const n = d(value || '0')
  let result
  if (n.gte(Math.pow(10, 9))) {
    result = addComma(fixRounding(n.div(Math.pow(10, 9))?.toString(), decimal)) + 'B'
  } else if (n.gte(Math.pow(10, 6))) {
    result = addComma(fixRounding(n.div(Math.pow(10, 6))?.toString(), decimal)) + 'M'
  } else if (n.gte(d(1000))) {
    result = addComma(fixRounding(n.div(1000)?.toString(), decimal)) + 'K'
  } else {
    result = addComma(fixRounding(Number(value), decimal))
  }
  return result
}

