export function fromDecimalsAmountFix(amount: number | string, decimals: number | string) {
  const amountF = fromDecimalsAmount(amount, decimals)
  return convertScientificToDecimal(amountF.toString(), Number(decimals))
}

/**
 * 将科学计数法表示的数字字符串转换为普通小数形式
 * @param numStr - 要转换的数字字符串
 * @param precision - 精度（保留的小数位数）
 * @returns 普通小数形式的字符串
 */
export function convertScientificToDecimal(numStr?: string, precision: number = 9): string {
  if (numStr === undefined) {
    return ''
  }
  // 转为小写以确保一致性
  const newNum = numStr.toLowerCase()

  // 检查是否包含科学计数法表示的 'e'
  if (newNum.includes('e')) {
    // 检查是否是 'e+' 格式
    if (newNum.includes('+')) {
      return fixDEAdd(newNum, precision)
    }

    // 'e-' 的情况
    const [base, exponentStr] = newNum.split('e')
    let integerPart = base
    const exponent = Math.abs(parseInt(exponentStr, 10)) // 获取指数部分的绝对值
    let zeros = ''
    let integerLength = integerPart.length

    // 检查小数点并移除小数点
    if (base.includes('.')) {
      const [intPart, fracPart] = base.split('.')
      integerPart = intPart + fracPart // 去掉小数点
      integerLength = intPart.length
    }

    // 生成必要的前导零
    for (let i = 0; i < exponent - integerLength; i++) {
      zeros += '0'
    }

    // 组合成普通小数格式
    return `0.${zeros}${integerPart}`.slice(0, precision + 2) // precision + 2 保证小数点后保留足够位数
  }

  // 如果不是科学计数法，直接返回
  return numStr
}

export const formatRelativeTime = (time?: number, isUnix?: boolean) => {
  if (!time) return null
  if (isUnix) {
    return dayjs.unix(time).fromNow()
  }
  return dayjs(time).fromNow()
}

export const formatCreatedTime = (time?: string | number, isUnix?: boolean) => {
  if (!time) return null
  let date
  if (isUnix) {
    date = dayjs.unix(time as number)
  } else {
    date = dayjs(Number(time) * 1000).valueOf()
  }
  const durationObj = dayjs.duration(dayjs().diff(date), 'ms')

  // 获取天、小时和分钟
  const days = durationObj.days()
  const hours = durationObj.hours()
  const minutes = durationObj.minutes()
  const timeAgo = `${days ? days + 'D' : ''} ${hours ? hours + 'H' : ''} ${minutes ? minutes + 'M' : ''}`
  return timeAgo
}

// 去掉百分号(为处理接口返回数据)
export const removePercentSign = (value: string) => {
  if (value?.includes('%')) {
    const arr = value.split('%')
    return d(arr?.[0]).equals('0') ? '0' : d(arr?.[0]).div(100).toString()
  }
  return value
}

// Symbol data display processing: 0.0001234 => <$0.01 or <0.0.1%
export function symbolDataDisplayProcessing(value: any, symbol = '$', decimal = 2) {
  if (value === '--') return '--'
  const min = Math.pow(10, -decimal)
  if (d(value).gt(0) && d(value).lt(min)) {
    if (symbol === '%') {
      return `<${min}${symbol}`
    }
    return `<${symbol}${min}`
  }
  if (symbol === '%') {
    return `${formatNumberWithDown(value, decimal)}${symbol}`
  }

  return `${symbol}${formatNumberWithDown(value, decimal)}`
}

/**
 * 数字缩写处理
 * @param number
 * @param decimals 原数值精度
 * @param abbreviationDecimals 缩写后数值精度
 * @returns
 */
export const numericAbbreviation = (number: string | number, decimals: number, abbreviationDecimals = 2) => {
  if (d(number).gte(1000000000)) {
    return d(number).div(1000000000).toFixed(abbreviationDecimals) + 'b'
  } else if (d(number).gte(1000000)) {
    return d(number).div(1000000).toFixed(abbreviationDecimals) + 'm'
  } else if (d(number).gte(1000)) {
    return d(number).div(1000).toFixed(abbreviationDecimals) + 'k'
  } else {
    return formatNumberWithDown(number.toString(), decimals)
  }
}
