import { useAccountStore } from '@cetus/stores'
import useTokenBalanceStore from '@cetus/stores/src/tokenBalance'
import { extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { CoinBalance } from '@mysten/sui/client'
import { useEffect } from 'react'
import { useInitSDK } from './useInitSDK'

export function useAccountBalance() {
  const { currentAccount } = useAccountStore()
  const { clmmSdk } = useInitSDK()
  const { setTokenBalanceObj, clearData, setIsLoading, isLoading, ownerAddress } = useTokenBalanceStore()

  const fetchAccountBalance = async (account: string = currentAccount?.address || '', forceRefresh: boolean = false) => {
    try {
      if (isLoading && !forceRefresh) {
        return
      }

      if (account) {
        setIsLoading(true)
        const res = await clmmSdk.getOwnerCoinBalances(account)
        const obj: Record<string, CoinBalance> = {}

        res.forEach(coin => {
          obj[extractStructTagFromType(coin.coinType).full_address] = coin
        })
        setTokenBalanceObj(obj, account)
      }
    } catch (error) {
      console.log('🚀 ~ file: useAccountBalance.ts:18 ~ fetchAccountBalance ~ error:', error)
      if (ownerAddress !== account) {
        clearData()
      }
    } finally {
      setIsLoading(false)
    }
  }

  const fetchCoinBalance = async (account: string = currentAccount?.address || '', coinType?: string) => {
    try {
      if (account && coinType) {
        const res = await clmmSdk.getOwnerCoinBalances(account, coinType)
        const obj: Record<string, CoinBalance> = {}

        res.forEach(coin => {
          obj[extractStructTagFromType(coin.coinType).full_address] = coin
        })
        setTokenBalanceObj(obj, account)
      }
    } catch (error) {
      console.log('🚀 ~ file: useAccountBalance.ts:18 ~ fetchCoinBalance ~ error:', error)
    }
  }

  useEffect(() => {
    if (!currentAccount) {
      clearData()
      setIsLoading(false)
    }
  }, [currentAccount])

  return {
    fetchAccountBalance,
    fetchCoinBalance,
    isLoading
  }
}
