import { Create } from '@/pages'
import { lazy } from 'react'
const Home = lazy(() => import('@/pages/Home'))
const Trade = lazy(() => import('@/pages/Trade/index'))
const Ranking = lazy(() => import('@/pages/Ranking'))
const Profile = lazy(() => import('@/pages/Profile'))
const TestUiKit = lazy(() => import('@/pages/TestUiKit'))
const WsTest = lazy(() => import('@/pages/WsTest'))

const routes = [
  {
    path: 'testuikit',
    element: <TestUiKit />
  },
  {
    path: 'home',
    element: <Home />
  },
  {
    path: 'profile',
    element: <Profile />,
    children: [
      {
        path: ':address',
        element: <Profile />
      }
    ]
  },
  {
    path: 'create',
    element: <Create />
  },
  {
    path: 'trade/:id',
    element: <Trade />,
    children: [
      {
        path: ':status',
        element: <Trade />
      }
    ]
  },

  {
    path: 'ranking',
    element: <Ranking />
  },
  {
    path: 'test-ws',
    element: <WsTest />
  }
]

export default routes
