import { Icon } from '@cetus/ui-kit'
import { Center, HStack, Image, Modal, ModalBody, ModalCloseButton, ModalContent, ModalOverlay } from '@chakra-ui/react'
import { useState } from 'react'

interface ImageViewerProps {
  src: string
  open: boolean
  onClose: () => void
}

export default function ImageViewer({ src, open, onClose }: ImageViewerProps) {
  const [zoom, setZoom] = useState(1)
  return (
    <Modal isOpen={open} onClose={onClose} colorScheme="blackAlpha" size="full">
      <ModalOverlay />
      <ModalContent bg="transparent" backdropFilter="blur(6px)" backgroundColor="rgba(0, 0, 0, 0.1)">
        <ModalCloseButton size="lg" />
        <ModalBody display="flex" justifyContent="center" alignItems="center">
          <Center>
            <Image src={src} transform={`scale(${zoom})`} w="100%" />
          </Center>
          <HStack position="absolute" bottom="100px" left="calc(50% - 44px)" w="88px" justify="space-between">
            <Icon fontSize="28px" svgFill="primary_gray" xlinkHref="#icon-a-icon_zoomin" cursor="pointer" onClick={() => setZoom(zoom - 0.2)} />
            <Icon fontSize="28px" svgFill="primary_gray" xlinkHref="#icon-a-icon_zoomout" cursor="pointer" onClick={() => setZoom(zoom + 0.2)} />
          </HStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
