import { Icon } from '@cetus/ui-kit'
import { HStack, Image, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, Text, useDisclosure } from '@chakra-ui/react'
import TokenAvatar from './TokenAvatar'

interface CoinSelectProps {
  value: any
  options: any[]
  onSelect: (value: any) => void
}

function CoinSelect({ value, options, onSelect }: CoinSelectProps) {
  const { isOpen, onOpen, onClose } = useDisclosure()

  return (
    <>
      <HStack onClick={onOpen} cursor="pointer">
        <TokenAvatar src={value?.image} />
        <Text>{value?.symbol}</Text>
        <Icon xlinkHref="#icon-icon_arrow" />
      </HStack>
      <Modal isOpen={isOpen} onClose={onClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Select Token</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {options?.map(item => (
              <HStack cursor="pointer" key={item.symbol} onClick={onSelect}>
                <Image src={item.image} />
                <Text>{item.symbol}</Text>
              </HStack>
            ))}
          </ModalBody>
        </ModalContent>
      </Modal>
    </>
  )
}

export default CoinSelect
