import envConfigs from '@cetus/types/src/config/envConfigs'
import { StateCreator, create } from 'zustand'

interface PumpTokenListState {
  currentDomain: string
  setCurrentDomain: (domain: string) => void
}

const store: StateCreator<PumpTokenListState> = (set, get) => ({
  currentDomain: envConfigs.pump_api.api_primary_domain,
  setCurrentDomain: (domain: string) => {
    set(() => ({
      currentDomain: domain
    }))
  }
})

const usePumpApiDomainStore = create(store)
export default usePumpApiDomainStore
