import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CommonTypeInfo, TransactionStatusType, WalletInfo, suiWalletList } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import {
  Grid,
  GridItem,
  HStack,
  Heading,
  Image,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalHeader,
  ModalOverlay,
  Text,
  VStack
} from '@chakra-ui/react'
import { useConnectWallet, useWallets } from '@mysten/dapp-kit'
import useGlobalToast from '../../../../hooks/src/useGlobalToast'

type ConnectWalletModalProps = {
  isOpen: boolean
  onClose: () => void
}

export default function ConnectWalletModal(props: ConnectWalletModalProps) {
  const { isOpen, onClose } = props
  const supportWalletList = useWallets()
  const { isApp } = useWindowWidth()
  const { mutate: connect } = useConnectWallet()

  const { customToast, successTsToast } = useGlobalToast()
  const handleConnectWallet = (wallet: WalletInfo) => {
    console.log('🚀 ~ file: ConnectWalletModal.tsx:30 ~ ConnectWalletModal ~ supportWalletList:', {
      supportWalletList,
      wallet
    })
    const walletObj = supportWalletList.find(item => item.name === wallet.walletName)
    if (!walletObj) {
      customToast(
        <VStack gap="8px" alignItems="start">
          <HStack>
            <Icon xlinkHref="#icon-icon_close" variant="error" />
            <Heading fontSize="14px" fontWeight="400" whiteSpace="nowrap" color="primary_red">
              Wallet Not Ready Error
            </Heading>
          </HStack>

          <HStack>
            <Text fontSize="14px" color="primary_gray" wordBreak="break-all">
              Please install
            </Text>
            <Text
              cursor="pointer"
              fontSize="14px"
              color="primary"
              wordBreak="break-all"
              onClick={() => {
                window.open(wallet.url, '_blank')
              }}
            >
              {wallet.name}
            </Text>
            <Text fontSize="14px" color="primary_gray" wordBreak="break-all">
              extension first
            </Text>
          </HStack>
        </VStack>
      )
      return
    }

    connect(
      { wallet: walletObj },
      {
        onSuccess: data => {
          successTsToast({
            getShowInfo: (_: TransactionStatusType): CommonTypeInfo => {
              const info: CommonTypeInfo = {
                iconUrl: wallet.icon.startsWith('http') ? wallet.icon : `/images/wallet/${wallet.icon}.png`,
                toastTitleText: `Wallet Connected`
              }
              return info
            }
          })
          onClose()
          console.log('🚀 ~ file: ConnectWalletMode.tsx:29 ~ handleConnectWallet ~ onSuccess:', wallet.name, data)
        },
        onError: error => {
          //TODO 链接失败，需要提示---没有钱包提示去下载 用户拒绝的话不提示
          console.log('🚀 ~ file: ConnectWalletMode.tsx:29 ~ handleConnectWallet ~ onError:', error)
        }
      }
    )
  }
  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <ModalOverlay />
      <ModalContent minW={isApp ? '300px' : '552px'}>
        <ModalHeader>Connect a Wallet</ModalHeader>
        <ModalCloseButton />
        <ModalBody p="16px" textAlign="center">
          <VStack>
            <Grid templateColumns={isApp ? 'repeat(2, 1fr)' : 'repeat(3, 1fr)'} gap={13} w="100%">
              {suiWalletList.map(item => (
                <GridItem key={item.name} colSpan={1}>
                  <HStack
                    gap="12px"
                    p="0 12px"
                    h="58px"
                    bg="bg_primary"
                    borderRadius="8px"
                    border="1px solid"
                    borderColor="border"
                    cursor="pointer"
                    _hover={{
                      bg: 'menu_item_hover_bg'
                    }}
                    onClick={() => handleConnectWallet(item)}
                  >
                    <Image
                      src={item.icon.startsWith('http') ? item.icon : `/images/wallet/${item.icon}.png`}
                      alt="SVG Image"
                      boxSize="36px"
                      objectFit="cover"
                      borderRadius="8px"
                    />
                    <Text textAlign="left" color="text_caption" whiteSpace="normal" wordBreak="break-word" overflowWrap="break-word">
                      {item.name}
                    </Text>
                  </HStack>
                </GridItem>
              ))}
            </Grid>
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
