import { useEffect, useState, useRef, useCallback } from 'react'
type noop = (...args: any[]) => any
export function useDebounceFunction<T extends noop>(callback: T, delay: number = 1000) {
  // 使用 useRef 保存一个变量，这个变量中存储的是 setTimeout 的返回值
  const debounceRef = useRef<any>()

  // 使用 useCallback 确保我们给事件处理器的函数身份保持不变
  // 如果不这么做，每次渲染都会创建一个新的 debouncedFunction
  // 并且旧的定时器会被清除，新的定时器会被设置
  const debouncedFunction = useCallback(
    (...args: Parameters<T>) => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current)
      }
      debounceRef.current = setTimeout(() => {
        callback(...args)
      }, delay)
    },
    [callback, delay]
  ) // 依赖项里包括回调函数和延迟时间

  // 清除定时器
  useEffect(() => {
    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current)
      }
    }
  }, []) // 这个 effect 没有依赖项，意味着它只会在组件卸载时运行

  return debouncedFunction
}

export function useDebounceValue(value: string, delay: number) {
  // 内部状态用于存储防抖后的值
  const [debouncedValue, setDebouncedValue] = useState(value)

  useEffect(() => {
    // 设置一个定时器，在延迟时间后更新防抖值
    const handler = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    // 清理函数：在下一个 effect 运行前清除定时器
    return () => {
      clearTimeout(handler)
    }
  }, [value, delay]) // 仅当 value 或 delay 变化时重新运行

  return debouncedValue
}
