import { d } from '@cetus/utils'
import { ChangeEvent } from 'react'
import { InputAttributes, NumericFormat, NumericFormatProps } from 'react-number-format'

interface NumericFormatInputParams extends Omit<NumericFormatProps<InputAttributes>, 'onChange'> {
  value: string
  decimals?: number
  placeholder?: string
  maxValue?: number
  minValue?: number
  inputAllowed?: boolean
  prefix?: string
  style?: Record<string, string | number>
  onChange: (value: string) => void
}

export default function NumericFormatInput(props: NumericFormatInputParams) {
  const { value, decimals, placeholder, style, onChange, maxValue, minValue = 0, inputAllowed = true, prefix, ...rest } = props

  const handleChange = (e: ChangeEvent<HTMLInputElement> | undefined) => {
    const inputValue = e?.target?.value

    if (inputValue) {
      let numericValue = String(inputValue).replace(/,/g, '')
      if (numericValue.startsWith('-')) {
        onChange('')
        return
      }
      if (prefix) {
        numericValue = numericValue.replace(prefix, '')
      }
      if (maxValue !== undefined && d(numericValue).gt(maxValue)) {
        numericValue = maxValue.toString()
      } else if (minValue !== undefined && d(numericValue).lt(minValue)) {
        numericValue = minValue.toString()
      }
      onChange(String(numericValue))
    } else {
      onChange('')
    }
  }
  return (
    <NumericFormat
      value={value}
      disabled={!inputAllowed}
      placeholder={placeholder}
      decimalScale={decimals}
      prefix={prefix}
      allowLeadingZeros
      thousandSeparator=","
      isAllowed={value => {
        return !value.value.startsWith('-')
      }}
      onChange={handleChange}
      {...rest}
      style={{
        ...style,
        cursor: inputAllowed ? 'pointer' : 'not-allowed'
      }}
    />
  )
}
