import { Pool } from '@/types'
import { useFetch } from '@cetus/hooks'
import { extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import useWrapPoolData from './useWrapPoolData'

type GetPoolListParams = {
  is_vaults: boolean
  display_all_pools: boolean
  has_mining: boolean
  has_farming: boolean
  no_incentives: boolean
  order_by: string
  limit?: number
  offset?: number
  coin_type?: string
  pool?: string
}

export default function useGetPoolList() {
  const { fetchByApi } = useFetch()
  const { wrapPoolData } = useWrapPoolData()

  const getPoolList = async (params: GetPoolListParams): Promise<Pool[]> => {
    try {
      const res = await fetchByApi('/v2/sui/stats_pools', 'GET', params)
      console.log('🚀 ~ file: useGetPoolList.ts:19 ~ getPoolList ~ res:', res)

      if (res?.lp_list) {
        const poolList = res?.lp_list?.map((item: any) => {
          return wrapPoolData(item)
        })

        console.log('🚀 ~ file: useGetPoolList.ts:25 ~ getPoolList ~ poolList:', poolList)
        return poolList
      }
    } catch (error) {
      console.error('getPoolList ~ Error:', error)

      return await getLocalJsonPoolList(params)
    }

    return []
  }

  // 获取本地Json pool list数据
  const getLocalJsonPoolList = async (params: GetPoolListParams) => {
    try {
      const res = await fetch('/data/pools.json').then(rsp => {
        return rsp.json()
      })
      console.log('🚀 ~ file: useGetPoolList.ts:44 ~ res ~ res:', res)
      if (res?.data?.lp_list) {
        const originList = res?.data?.lp_list
        let list = originList
        console.log('🚀 ~ file: useGetPoolList.ts:48 ~ getLocalJsonPoolList ~ res?.lp_list:', res?.lp_list)

        // 支持coin_type筛选
        if (params?.coin_type) {
          const coinArr = params?.coin_type?.split(',')?.map(item => extractStructTagFromType(item).source_address)
          console.log('🚀 ~ file: useGetPoolList.ts:48 ~ getLocalJsonPoolList ~ coinArr:', coinArr)
          list = originList?.filter((item: any) => {
            const coinTypeA = extractStructTagFromType(item?.coin_a?.address).source_address
            console.log('🚀 ~ file: useGetPoolList.ts:48 ~ list=res?.data?.lp_list?.filter ~ coinTypeA:', coinTypeA)
            const coinTypeB = extractStructTagFromType(item?.coin_b?.address).source_address
            console.log('🚀 ~ file: useGetPoolList.ts:48 ~ list=res?.data?.lp_list?.filter ~ coinTypeB:', coinTypeB)
            if (coinArr?.length > 1 && coinArr.includes(coinTypeA) && coinArr.includes(coinTypeB)) {
              return true
            } else if (coinArr?.length === 1 && (coinArr.includes(coinTypeA) || coinArr.includes(coinTypeB))) {
              return true
            } else {
              return false
            }
          })
        }

        // 支持vaults筛选
        if (params?.is_vaults) {
          list = originList?.filter((item: any) => item?.is_vaults)
        }

        // 支持farms筛选
        if (params?.has_farming && !params?.is_vaults && !params?.has_mining && !params?.no_incentives) {
          list = originList?.filter((item: any) => item?.has_farming)
        }

        console.log('🚀 ~ file: useGetPoolList.ts:48 ~ list=res?.lp_list.filter ~ list:', list)

        const poolList = list?.map((item: any) => {
          return wrapPoolData(item, true)
        })

        return poolList
      }
    } catch (error) {
      console.error('getLocalJsonPoolList Error:', error)
    }

    return []
  }

  return {
    getPoolList,
    getLocalJsonPoolList
  }
}
