import { create } from 'zustand'

interface ToastState {
  toastId: number
  accumulateToastId: () => void
}

const useToastStore = create<ToastState>((set, get) => ({
  toastId: 0,
  accumulateToastId: () => {
    const toastId = get().toastId + 1
    set(() => ({
      toastId
    }))
    return toastId
  }
}))

export { useToastStore }
