import usePumpApiDomainStore from '@/store/apiDomain'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { fetchGet, fetchPost } from '@cetus/utils'

export function usePumpApiDomain(autoSwitch = true) {
  const { currentDomain, setCurrentDomain } = usePumpApiDomainStore()

  const fetchGetByApi = async (endpoint: string, domain: string = currentDomain, options?: any): Promise<any> => {
    console.log('🚀 ~ file: usePumpApiDomain.ts:18 ~ fetchGetByApi ~ currentDomain:', domain)
    try {
      const response = await fetchGet(`${domain}${endpoint}`, options)
      return response
    } catch (error) {
      console.log('🚀 ~ file: usePumpApiDomain.ts:19 ~ fetchGetByApi ~ error:', error)
      const backupDomain = envConfigs.pump_api.api_backup_domain
      const isPrimary = isPrimaryDomain(domain)
      // 切换到备用域名重试
      if (autoSwitch && isPrimary && backupDomain) {
        console.log('🚀 ~ file: usePumpApiDomain.ts:23 ~ fetchGetByApi ~ setCurrentDomain:', envConfigs.pump_api.api_backup_domain)
        setCurrentDomain(backupDomain)
        return await fetchGetByApi(endpoint, backupDomain, options)
      }
      throw error
    }
  }

  const fetchPostByApi = async (endpoint: string, domain: string = currentDomain, options?: any): Promise<any> => {
    try {
      const response = await fetchPost(`${domain}${endpoint}`, options)
      return response
    } catch (error) {
      const backupDomain = envConfigs.pump_api.api_backup_domain
      const isPrimary = isPrimaryDomain(domain)

      // 切换到备用域名重试
      if (autoSwitch && isPrimary && backupDomain) {
        setCurrentDomain(backupDomain)
        return await fetchPostByApi(endpoint, backupDomain, options)
      }
      throw error
    }
  }

  return { fetchGetByApi, fetchPostByApi }
}

function isPrimaryDomain(domain?: string) {
  return domain === envConfigs.pump_api.api_primary_domain
}
