import { ToastType } from '@cetus/types/src/common-types'
import { create } from 'zustand'

interface TransactionState {
  transactionModalVisible: boolean
  transactionData: ToastType | undefined
  setTransactionModalVisible: (value: boolean) => void
  setTransactionData: (data: ToastType) => void
}

const useTransactionStore = create<TransactionState>((set, get) => ({
  transactionModalVisible: false,
  transactionData: undefined,

  setTransactionModalVisible: (value: boolean) => {
    set(() => ({
      transactionModalVisible: value
    }))
  },

  setTransactionData: (data: ToastType) => {
    set(() => ({
      transactionData: data
    }))
  }
}))

export { useTransactionStore }
