import { Icon } from '@cetus/ui-kit'
import { Box, Center, Divider } from '@chakra-ui/react'
import TradeInput, { TradeInputProps } from './TradeInput'

export interface TradeInputGroupProps {
  from: Omit<TradeInputProps, 'position'>
  to: Omit<TradeInputProps, 'position'>
  icon: string
  onClick?: () => void
  loading?: boolean
  byAmountIn?: boolean
}

function TradeInputGroup({ from, to, icon, onClick = () => {}, loading, byAmountIn }: TradeInputGroupProps) {
  return (
    <Box w="100%" bg="bg_secondary" borderRadius="20px" border="1px solid" borderColor="border" position="relative">
      <TradeInput {...from} position="top" loading={!byAmountIn && loading} />
      <Center p="0px 24px" mt="-1px">
        <Divider borderColor="border" />
      </Center>
      <TradeInput {...to} position="bottom" loading={byAmountIn && loading} />
      <Center
        w="36px"
        h="36px"
        borderRadius="50%"
        position="absolute"
        top="calc(50% - 18px)"
        left="calc(50% - 18px)"
        border="2px solid"
        borderColor="border"
        boxShadow="trade_icon_shadow"
        bg="input_bg"
        onClick={onClick}
      >
        <Icon xlinkHref={icon} svgFill="text_caption" fontSize="12px" />
      </Center>
    </Box>
  )
}

export default TradeInputGroup
