import useGetPoolList from '@/hooks/pool/useGetPoolList'
import { Pool } from '@/types'

export default function useGetApiPoolInfo() {
  const { getPoolList } = useGetPoolList()

  // 根据池子地址获取api池子详情
  const getApiPoolInfo = async (pool: string): Promise<Pool | null> => {
    const res = await getPoolList({
      is_vaults: false,
      display_all_pools: true,
      has_mining: true,
      has_farming: true,
      no_incentives: true,
      order_by: '-vol',
      pool
    })
    console.log('🚀 ~ file: useGetApiPoolInfo.ts:16 ~ getApiPoolInfo ~ res:', res)

    return res?.[0] || null
  }

  // 获取指定coinA, coinB的所有池子，主要用在feetier下拉框占比计算等
  const getCoinABApiPools = async (coinType: string): Promise<Pool[]> => {
    const res = await getPoolList({
      is_vaults: false,
      display_all_pools: true,
      has_mining: true,
      has_farming: true,
      no_incentives: true,
      order_by: '-vol',
      coin_type: coinType
    })

    return res || []
  }

  return {
    getApiPoolInfo,
    getCoinABApiPools
  }
}
