import { ExcludeCNCharRegex } from '@cetus/design'

export function crateValidate(name: string, cb?: (value: any) => string | undefined) {
  return (value: any) => {
    let error
    if (!value) {
      error = `${name} is required`
    }
    if (cb && value) {
      error = cb(value)
    }
    return error
  }
}

export const excludeCharValidate = (name: string, cb?: (value: any) => string | undefined) => {
  return (value?: string) => {
    if (value) {
      if (!ExcludeCNCharRegex.test(value)) {
        return `${name} cannot contain Chinese characters`
      }
      if (cb) {
        return cb(value)
      }
    }
  }
}

